/** Long-form companions to BOOKS, keyed by title. Drafts until reviewed (reviews.ts). */
import type { Depth } from "./depth-types.js";
export const DEPTH_BOOKS: Record<string, Depth> = {
"The Muqaddimah": { sections: [
  { h: "What it is", p: [ "Ibn Khaldun wrote the Muqaddimah, the Introduction, as the opening volume of a universal history, in 1377, in the fortress of Qal'at Ibn Salama in what is now Algeria, after a career in the courts of Tunis, Fez, Granada and Bougie had taught him how dynasties actually rise and fall. He meant it as a new science: the study of human society, umran, its forms and the laws that govern its changes. Historians before him, he argued, repeated reports without testing them against what is possible for societies; he set out the test.", "The book runs through six long chapters: human civilisation in general and the influence of climate and food; desert and tribal life; dynasties, kingship and the caliphate; towns and cities; the crafts and ways of earning a living; and the sciences and education. It is at once sociology, economics, political theory, pedagogy and a theory of history, written before any of those words existed." ] },
  { h: "The main ideas", l: [ "'Asabiyyah, group feeling: the bond that makes people fight and sacrifice for one another. Dynasties are founded by groups with strong 'asabiyyah, usually from the hard life of the desert or the margins.", "The cycle of generations: the founders are hardy and united; their children keep the state by imitation; the grandchildren, raised in luxury, lose the feeling and the skill, and a new group with fresh 'asabiyyah replaces them. He gives a dynasty about three generations, roughly a hundred and twenty years.", "Luxury and taxation: as a dynasty ages, its needs grow, taxes rise, enterprise falls, and the revenue that heavy taxes were meant to raise falls with it. The observation was repeated by economists six centuries later.", "Cities and crafts: sedentary life produces the crafts, sciences and refinement, and also the softness that ends it. Civilisation is both the goal and the solvent of the strength that built it.", "Religion and 'asabiyyah: religious conviction multiplies group feeling, since it removes rivalry and fear of death; but religion without group feeling cannot found a state.", "Education: he criticises teaching by memorised summaries, recommends gradual exposure to a subject in three passes, and warns that harsh discipline makes children deceitful." ] },
  { h: "Why it still matters", p: [ "The Muqaddimah is the first book to treat the course of history as something with causes that can be studied rather than a chain of events to be recorded. Its account of how prosperity undoes the discipline that produced it describes families and companies as well as empires, and its remarks on taxation, on the value of labour, and on how to teach are modern. Arnold Toynbee called it the greatest work of its kind ever created by any mind in any time or place." ] },
  { h: "For our family", l: [ "A family is the smallest dynasty. Its 'asabiyyah is built at the dinner table, in shared hardship and shared worship, not in comfort.", "The third-generation problem is a warning to parents: children raised without any hardness lose what their grandparents had. Choose a few hard things to keep.", "His rule for teaching, three gradual passes rather than one hard one, is how the Learn tab works: a short line, a longer version, a review later." ] },
  { h: "Read next", l: [ "The chapters on 'asabiyyah (Chapter 2) and on the sciences (Chapter 6) in Franz Rosenthal's translation, or the one-volume abridgement edited by N. J. Dawood.", "Robert Irwin, Ibn Khaldun: An Intellectual Biography (2018), for the man and the misreadings." ] } ],
  kids: [ "Ibn Khaldun lived about six hundred and fifty years ago. He watched kings and kingdoms rise and fall and asked: why does this keep happening?", "He found that a group of people who stick together like a family can build something great. But when their grandchildren grow up too comfortable and stop sticking together, it falls apart.", "So he wrote a huge book explaining it. Even today people read it to understand countries, companies and families. The secret is simple: stay together, and do not get soft." ] },

"The Canon of Medicine": { sections: [
  { h: "What it is", p: [ "Ibn Sina, known in Europe as Avicenna, completed al-Qanun fi al-Tibb around 1025. It gathers Greek medicine from Hippocrates and Galen, the Islamic physicians before him such as al-Razi, and his own clinical observation into one ordered system in five books: the principles of medicine, including anatomy, physiology and hygiene; simple drugs, listed alphabetically with their properties; diseases of particular organs, from head to foot; diseases that affect the whole body, such as fevers, and surgery; and compound drugs.", "It was translated into Latin in the twelfth century and remained a textbook in Montpellier, Louvain and other European universities into the seventeenth century. The author was also a philosopher, and wrote it in the same decades as his great philosophical summa, the Shifa." ] },
  { h: "The main ideas", l: [ "Health is a balance, of the humours in his language, of the body's systems in ours; disease is an imbalance, and the physician's first task is to restore it by diet, sleep, movement and climate before drugs.", "The six necessities of health: air, food and drink, movement and rest, sleep and waking, retention and evacuation, and the states of the soul. Emotion is a medical factor.", "Testing drugs: the Canon sets out rules for a trial, including that a drug must be tested on the disease in its pure form, that the dose must match the strength of the disease, and that the effect must be consistent and observed on humans, since a drug may act differently in animals.", "Hygiene and exercise: a long section on regimen, with exercise described as the most important of the preservers of health, to be done before meals, and sleep recommended at night and in moderation.", "The description of contagion, the role of water and soil in disease, and the first clear accounts of several conditions." ] },
  { h: "Why it still matters", p: [ "Much of the Canon's physiology has been replaced. Its method has not: the physician who looks at diet, sleep, movement and mood before reaching for medicine, and who tests a remedy against clear rules, is practising what Ibn Sina described. The rules for a drug trial are often cited as the earliest statement of principles that later became the controlled trial." ] },
  { h: "For our family", l: [ "OnePlate's order of priorities, food, sleep, movement, mood, then anything else, is the Canon's order.", "Ibn Sina's rule that exercise comes before meals is the morning walk before suhoor-like breakfast on a non-fasting day, and the walk before the plate.", "His sixth necessity, the states of the soul, is why the Today tab asks about mood and gratitude beside steps and water." ] },
  { h: "Read next", l: [ "The first book of the Canon in O. Cameron Gruner's English (1930), or the selections in Nancy Siraisi's Avicenna in Renaissance Italy for how it was taught.", "Ibn Sina's Poem on Medicine, a short verse summary, is a quicker way in." ] } ],
  kids: [ "Ibn Sina was a doctor who lived a thousand years ago. He wrote a giant book about how the body works and how to stay well.", "He said the best medicine is simple: good air, good food, moving your body, sleeping well, and keeping a calm heart. Only after that should a doctor give medicine.", "Doctors in Europe used his book for six hundred years. Many things he said, like exercise before eating and sleeping at night, we still do today." ] },

"The Masnavi": { sections: [
  { h: "What it is", p: [ "Jalal al-Din Rumi dictated the Masnavi-ye Ma'navi, the Spiritual Couplets, to his student Husam al-Din Chalabi over the last fifteen years of his life in Konya, between about 1258 and his death in 1273. It is six books of rhyming couplets, more than twenty-five thousand lines, in which stories within stories carry teaching on the soul's journey to God. Rumi calls it the roots of the roots of the roots of religion, and the Persian tradition has called it the Quran in the Persian tongue because it is so saturated with Quranic verses and prophetic reports.", "It opens with the Song of the Reed: listen to the reed and the tale it tells, how it sings of separation. The reed cut from the reed-bed is the soul cut from its source, and its music is longing." ] },
  { h: "The main ideas", l: [ "Separation and return: every soul is a reed cut from the bed; the ache of longing is itself the proof of where we came from and the engine of the way back.", "The story is the door: Rumi never argues in the abstract for long. A merchant and a parrot, a lion and a hare, a king and a handmaiden, each carries one truth about desire, pride, trust or love, and the digressions are the teaching.", "The nafs, the commanding self: most of the Masnavi's villains are the reader's own appetites and self-regard, disguised as other people.", "Love over reason: reason is a lamp, love is the sun; reason gets you to the door, love opens it. He is not against reason, he ranks it.", "Allah's mercy outruns His justice, and the Prophet's character is the model of that mercy. The Masnavi is a long commentary on the mercy to the worlds." ] },
  { h: "Why it still matters", p: [ "The Masnavi is the most read work of mystical poetry in the world, in Persian, Turkish and Urdu for seven centuries, and in English since the twentieth. Its stories are told to children and studied by scholars because they work at both levels. It teaches without lecturing, which is why it has outlived every treatise written in the same years." ] },
  { h: "For our family", l: [ "The Masnavi is a family book in the Persian and Urdu world: a story a night, with the moral found by the listener. The Poem of the day borrows that habit.", "Its lesson about the nafs fits the fast: the appetite is a character in the story, and it can be taught.", "Rumi's own teacher was the friend who told him the truth. Find the friend who will." ] },
  { h: "Read next", l: [ "Jawid Mojaddedi's verse translation of Books One to Six (Oxford World's Classics), the best complete English Masnavi.", "Reynold Nicholson's full translation and commentary for study. Start with Book One: the reed, the king and the handmaiden, the merchant and the parrot." ] } ],
  kids: [ "Rumi was a teacher in Turkey about eight hundred years ago. Instead of giving lectures, he told stories: about a parrot who wanted to be free, a lion and a clever rabbit, a man who kept making the same mistake.", "Every story has a secret lesson inside about loving Allah and being a better person. His book of stories is so long it has six parts, and people still read it in Persian, Turkish, Urdu and English.", "It starts with a flute made from a reed. The flute sounds sad because it misses the field it came from. Rumi says our hearts are like that: they miss Allah, and that is why we pray." ] },

"The Gulistan": { sections: [
  { h: "What it is", p: [ "Saadi of Shiraz finished the Gulistan, the Rose Garden, in 1258, a year after the Bustan, after decades of travel from Syria to India. It is eight chapters of short anecdotes in rhymed prose, each capped with a verse: on the manners of kings, the morals of dervishes, the excellence of contentment, the advantages of silence, love and youth, weakness and old age, the effects of education, and rules for conduct in life. For six hundred years it was the first Persian book a child read after the Quran, from Istanbul to Delhi, and it is still memorised in Iran.", "Saadi's own preface explains the title: the roses of a real garden fade in days; this garden will last." ] },
  { h: "The main ideas", l: [ "Wisdom is practical. Saadi is interested in how a merchant, a king, a dervish or a father should actually behave, and his heroes are the ones who answer wisely under pressure.", "Contentment protects freedom: the man who wants little cannot be bought. The chapter on contentment is a manual for not being owned.", "Silence is a skill: he who speaks before he thinks pays, and the chapter on silence is full of men who could not keep a secret.", "Kindness across difference: the famous lines from Chapter 1 that human beings are members of one body, so that no one who is untouched by another's pain deserves the name of human.", "Education forms, nature limits: the chapter on upbringing argues that teaching works on a good nature and is wasted on a bad one, but that no one knows which a child has until they have tried." ] },
  { h: "Why it still matters", p: [ "The Gulistan trained the manners of a civilisation. Its anecdotes gave Persian, Turkish and Urdu their proverbs, and the Bani Adam lines greet visitors at the United Nations. It is short, funny, worldly and devout at once, which is rarer than it sounds." ] },
  { h: "For our family", l: [ "One anecdote a night at the table, with the question: what would you have said? Saadi's stories are two minutes long and built for this.", "The chapter on silence is the cure for the family argument: who speaks last, wins; who speaks first, pays.", "His chapter on contentment is the fast's philosophy in prose: enough is a decision." ] },
  { h: "Read next", l: [ "Wheeler Thackston's translation (Ibex, 2008) is the most faithful; Edward Rehatsek's older version is free online.", "Then the Bustan, his earlier book in verse, for the same wisdom at greater length." ] } ],
  kids: [ "Saadi was a poet who travelled everywhere for thirty years and then came home to Shiraz and wrote down the best stories he had heard and seen.", "His book is called the Rose Garden. It is full of short stories about kings, poor wise men, teachers and children, each with a lesson at the end.", "One of his poems says all people are like parts of one body: if your toe hurts, your whole body feels it. That poem is written on the wall of the United Nations, where all the countries meet." ] },

"The Revival of the Religious Sciences": { sections: [
  { h: "What it is", p: [ "Abu Hamid al-Ghazali wrote Ihya 'Ulum al-Din in the years after he left his professorship in Baghdad in 1095, a crisis of sincerity he describes in his autobiography, and spent a decade in seclusion and travel. The Ihya is forty books in four quarters: acts of worship, from knowledge and belief to prayer, zakat, fasting, pilgrimage and the Quran; the norms of daily life, from eating and marriage to earning, friendship, travel and enjoining good; the things that destroy, the vices of the heart, from the stomach and the tongue to anger, envy, love of the world, pride and self-delusion; and the things that save, repentance, patience, gratitude, fear and hope, poverty, tawhid and trust, love, intention, self-examination, meditation and the remembrance of death.", "Its purpose is in the title: to revive religious knowledge by reconnecting the law with the heart that the law is for." ] },
  { h: "The main ideas", l: [ "Knowledge that does not change the knower is a danger, not a merit; the first book is on knowledge and most of it is on the scholar's own sincerity.", "The heart is the battlefield. Outward acts matter because of what they do inside, and the vices of the heart, not the limbs, are what destroy.", "Habit is cure: a vice is removed by practising its opposite until the new act becomes natural; a miser gives until giving is easy.", "The stomach first: the book on the discipline of eating opens the quarter on vices, because appetite for food is the root appetite and the one most easily trained.", "Death remembered: the last book, on the remembrance of death and the afterlife, is the lens that puts every earlier chapter in proportion." ] },
  { h: "Why it still matters", p: [ "The Ihya is the most influential book of Islamic spirituality ever written, read across every school and region; its books on the discipline of the soul, on marriage, on the manners of eating and on patience and gratitude are still the standard works. Its method, naming the vice, tracing its cause, prescribing the opposite practice, is what modern habit science rediscovered." ] },
  { h: "For our family", l: [ "The book on the discipline of eating is OnePlate's ancestor: eat when hungry, stop before full, do not make the stomach the aim of the day.", "The quarter on things that save gives the Today tab its check-ins: gratitude, patience, intention, self-examination.", "Al-Ghazali's practice of replacing a vice with its opposite act is how to handle a child's habit as well as one's own." ] },
  { h: "Read next", l: [ "Start with the Book of the Discipline of Eating (Book 11) and the Book on Patience and Thankfulness (Book 32), both in the Islamic Texts Society's translations.", "His short autobiography, Deliverance from Error, explains why he wrote it." ] } ],
  kids: [ "Al-Ghazali was one of the most famous teachers in the world about nine hundred years ago. One day he realised that he was teaching for fame, not for Allah, so he left his job and went away to fix his own heart.", "Then he wrote forty small books in one big one, explaining how to pray, how to eat, how to be patient, how to stop being angry or jealous, and how to remember that life is short.", "His big idea is that what matters most is what is inside you. A bad habit can be fixed by doing the opposite thing again and again until the good thing becomes easy." ] },

"Nicomachean Ethics": { sections: [
  { h: "What it is", p: [ "Aristotle's lectures on how to live well, edited after his death, probably by or for his son Nicomachus, around 340 BCE. Ten books: the human good as happiness, eudaimonia, understood as the activity of a life lived well; moral virtue as a state of character formed by habit; the particular virtues, courage, temperance, generosity, magnificence, proper pride, good temper, friendliness, truthfulness, wit, and justice; the intellectual virtues, including practical wisdom; weakness of will; pleasure; two books on friendship; and the contemplative life as the highest happiness.", "Islamic philosophers read it in Arabic from the ninth century; Ibn Miskawayh's Refinement of Character and al-Ghazali's Ihya both carry its doctrine of the mean, and al-Farabi and Ibn Rushd commented on it." ] },
  { h: "The main ideas", l: [ "Happiness is not a feeling but an activity: a life of rational activity in accordance with virtue, over a complete life.", "Virtue is a habit: we become just by doing just acts, brave by doing brave acts. Character is the deposit of repeated choices.", "The mean: each virtue lies between two vices, an excess and a deficiency, relative to us. Courage sits between cowardice and recklessness; generosity between meanness and waste.", "Practical wisdom, phronesis: the virtue that finds the mean in a particular case; without it the other virtues misfire.", "Friendship is a virtue and a necessity: friendships of pleasure and of utility pass; friendship of the good, in which each wishes the other's good for the other's sake, is rare and lasting.", "The role of pleasure and pain: the good person takes pleasure in good acts; education is largely learning to enjoy the right things." ] },
  { h: "Why it still matters", p: [ "It is the founding text of virtue ethics and the most read book of moral philosophy in the world. Its claim that character is formed by practice, that the virtues are means, and that happiness is a life rather than a mood, has been absorbed by Islamic, Christian and secular thought alike, and modern psychology on habit and on flourishing keeps confirming it." ] },
  { h: "For our family", l: [ "The mean is the rule of thirds in philosophy: food between starving and stuffing, exercise between sloth and injury, speech between silence and chatter.", "Children become brave by doing brave things: small chosen difficulties, not lectures.", "Friendship of the good: the people who want you to be better. Notice who those are." ] },
  { h: "Read next", l: [ "Terence Irwin's or Roger Crisp's translation; read Books I, II and VIII first.", "Ibn Miskawayh, The Refinement of Character, for the Islamic reception." ] } ],
  kids: [ "Aristotle was a teacher in Greece more than two thousand years ago. He asked: what makes a life a good life?", "His answer: you become good by doing good things over and over, until they become a habit. Nobody is born brave; you become brave by doing brave things.", "He also said the best way is usually in the middle. Being brave is between being a coward and being reckless. Eating well is between eating nothing and eating everything." ] },

"The Republic": { sections: [
  { h: "What it is", p: [ "Plato's dialogue, written around 375 BCE, in which Socrates and a group of friends ask what justice is and whether the just person is happier than the unjust. To find justice in the soul, Socrates proposes to find it first in a city, writ large, and the dialogue builds an ideal city in speech: three classes, the producers, the guardians who defend, and the rulers who are philosophers; a long programme of education in music and gymnastics; the community of the guardians; the famous images of the sun, the divided line and the cave; a theory of the decline of regimes from aristocracy through timocracy, oligarchy and democracy to tyranny; a critique of the poets; and the closing myth of Er on the soul's choice of its next life.", "Al-Farabi built his Virtuous City on it, and Ibn Rushd wrote a commentary on it when he could not find Aristotle's Politics." ] },
  { h: "The main ideas", l: [ "Justice as order: in the soul, reason rules, spirit supports and appetite obeys; in the city, each class does its own work. Injustice is the lower part ruling the higher.", "The cave: most people see shadows on a wall and take them for things; education is the painful turning of the whole soul toward the light, and the one who has seen must go back down to help.", "Philosophers should rule, or rulers should philosophise: power without knowledge of the good is dangerous, and knowledge that refuses to govern leaves the city to the worst.", "Education forms the soul: what children hear and see shapes what they love; hence the care about stories, music and models.", "The decline of regimes follows the decline of desires: as a people wants more and rules itself less, its government changes to match." ] },
  { h: "Why it still matters", p: [ "The Republic set the questions of political philosophy and the philosophy of education for everything after it. Its warning that a people gets the government its appetites deserve, and its image of the cave, remain the clearest descriptions we have of what learning costs and why it is resisted." ] },
  { h: "For our family", l: [ "The house is the first city. Plato's rule, each does his own work, is the chore list and the family circle.", "The cave is the phone: shadows that feel like life. Turning the soul around is uncomfortable, which is why it has to be practised.", "What children hear shapes what they love. The Learn tab's stories are chosen on that principle." ] },
  { h: "Read next", l: [ "Allan Bloom's or C. D. C. Reeve's translation; read Books I, II, IV, VII and the end of X.", "Al-Farabi, On the Perfect State, for the Islamic version of the city." ] } ],
  kids: [ "Plato was a Greek thinker who wrote down conversations with his teacher Socrates. In this one they ask: what does it mean to be fair, and is a fair person happier?", "Plato's most famous story is about people chained in a cave, watching shadows on a wall, thinking the shadows are real. One person gets out, sees the sun, and comes back to tell the others. They do not believe him.", "The lesson: learning can feel strange at first, like bright light after the dark, but it is the only way to see what is really there." ] },

"The Analects": { sections: [
  { h: "What it is", p: [ "The Analects, Lunyu, are sayings and short conversations of Confucius (551–479 BCE) with his students, compiled by his followers over the generations after his death. Twenty short books, in no strict order, about the gentleman, junzi, the person of cultivated character; benevolence, ren; ritual propriety, li; filial piety; learning; government by moral example; and the Way. For two thousand years it was the foundation of education in China, Korea, Japan and Vietnam, and the text every official was examined on." ] },
  { h: "The main ideas", l: [ "The gentleman is made, not born: by learning, by ritual and by practising benevolence until it is natural. Is it not a pleasure to learn and then to practise what you have learned?", "Ren, humaneness: the virtue of treating others as persons; do not impose on others what you do not wish for yourself.", "Li, ritual: the forms of respect, in greeting, mourning, eating and speaking, that train the heart from the outside in.", "Filial piety: the root of benevolence is learned at home, in how a child treats parents and elders; the family is the school of the state.", "Government by example: a ruler who is correct need not command; the people follow like grass bending in the wind.", "Rectification of names: let a father be a father, a son a son; disorder begins when words and roles stop matching." ] },
  { h: "Why it still matters", p: [ "No book has shaped more people's manners. Its claims that character is cultivated, that ritual shapes feeling, that the family is the first school and that leaders teach by example are confirmed daily. Readers from the Islamic world find in Confucius a companion to adab." ] },
  { h: "For our family", l: [ "Li is adab: the manners of eating, greeting and speaking are not decoration but training. The mindful dinner is a ritual in Confucius's sense.", "Filial piety is the Quran's kindness to parents stated as a civilisation's foundation.", "Teach by being: the parent who reads is the lesson on reading." ] },
  { h: "Read next", l: [ "Edward Slingerland's translation with traditional commentary, or D. C. Lau's; read Books I, II, IV and XII first.", "Then the Mencius, the other great Confucian text, for the argument that human nature is good." ] } ],
  kids: [ "Confucius was a teacher in China about two and a half thousand years ago. His students wrote down the wise things he said, and the book is called the Analects.", "He said a good person is made by learning and practising, like a musician, not born that way. He said good manners are not silly; they train your heart to respect people.", "His most famous rule is: do not do to others what you would not want done to you. And he said a family that treats its parents and elders with love is the beginning of a good country." ] },

"Meditations": { sections: [
  { h: "What it is", p: [ "The private notebooks of Marcus Aurelius, Roman emperor from 161 to 180, written in Greek during the campaigns on the Danube, never meant for publication. Twelve books of short reflections addressed to himself: reminders of Stoic doctrine, rebukes, gratitude to his teachers in the first book, and repeated attempts to meet the day's duty with a calm mind. The title is a later editor's; his own heading was something like 'to himself'." ] },
  { h: "The main ideas", l: [ "Distinguish what is in your power, your judgements and choices, from what is not, and spend yourself on the first.", "The present is all you have: the past is gone and the future not yet; a life is a succession of present moments met well or badly.", "Do your duty as a part of the whole: you were made for cooperation, like hands and feet; what harms the hive harms the bee.", "Expect difficult people, and meet them with patience, since they act from ignorance of the good, and you share a nature with them.", "Remember death and the smallness of fame: those who praised you will die too; what remains is whether you acted justly.", "Take the view from above: see the city, the empire, the earth from a height, and the troubles of the day shrink to their size." ] },
  { h: "Why it still matters", p: [ "A ruler of the known world writing at night about how to be patient with a rude official, how to get out of bed, and how to accept what he could not change is a rare document of a person working on himself. It has been read for that honesty for eighteen centuries. Its practice, the morning rehearsal of difficulties and the evening review, is the Islamic muhasabah in Roman dress." ] },
  { h: "For our family", l: [ "Marcus's morning sentence, today I will meet people who are meddling, ungrateful and rude, is a parent's preparation for a long day.", "The view from above is a cure for the family argument: how big is this from the roof?", "Control what you can: the plate, the walk, the bedtime. Outcomes belong to Allah; in Marcus's language, to nature." ] },
  { h: "Read next", l: [ "Gregory Hays's translation (Modern Library) reads best; read Books II, IV and V, and the first book for his gratitude to his teachers.", "Epictetus, the Enchiridion, the handbook Marcus himself studied." ] } ],
  kids: [ "Marcus Aurelius was the emperor of Rome, the most powerful man in the world. At night, in his army tent, he wrote notes to himself about how to be a good person.", "He wrote things like: when I wake up, I will meet people who are rude today, and I will stay calm because getting angry does not help. And: I cannot control what happens, only what I do.", "He never meant anyone to read it, but the notebook survived, and people still read it to learn how to stay calm and do their job well." ] },

"Confessions": { sections: [
  { h: "What it is", p: [ "Augustine, bishop of Hippo in North Africa, wrote the Confessions around 400 as a prayer addressed to God in thirteen books: nine of autobiography, from infancy through his schooling at Carthage, his years as a Manichee, his teaching of rhetoric in Rome and Milan, his mother Monica's persistence, the conversion in the garden, and her death; a tenth on memory and the self; and three on time, creation and the opening of Genesis. It is the first great autobiography in any language, and its question is the one in its first page: our heart is restless until it rests in You." ] },
  { h: "The main ideas", l: [ "The restless heart: desire is unbounded, and every finite object fails it; the restlessness is a sign of what the heart was made for.", "The stolen pears: he steals fruit he does not want, with friends, for the pleasure of the theft, and discovers that evil is often done for no reason but the company and the thrill.", "Habit as a chain: he describes his inability to leave his old life as links of a chain forged by repeated choice, and his will as divided against itself.", "Memory as a vast palace in which the self and God are sought; the tenth book is the first philosophy of memory.", "Time: what is time? If no one asks me, I know; if I try to explain, I do not. Time is a distension of the mind between memory, attention and expectation.", "A mother's prayer: Monica's decades of patient prayer for her son are the book's steady background." ] },
  { h: "Why it still matters", p: [ "The Confessions invented the inner life as a subject. Its analysis of divided will and chained habit anticipates everything written on addiction; its treatment of memory and time started philosophy on both. A Muslim reader finds in it a neighbour's account of tawbah, the turning, with the same honesty al-Ghazali would show six centuries later." ] },
  { h: "For our family", l: [ "The pears: children's wrongdoing is often for the company, not the thing. Ask who was there.", "The chain of habit is forged by small repeated choices and broken the same way.", "Monica is the mother who did not stop praying. Her son was forty-two when he changed." ] },
  { h: "Read next", l: [ "Henry Chadwick's or Sarah Ruden's translation; read Books I, II, VIII and X.", "Al-Ghazali's Deliverance from Error, the Islamic parallel, is a short companion." ] } ],
  kids: [ "Augustine lived in North Africa about sixteen hundred years ago. When he was young he did many wrong things, even stealing pears he did not want, just because his friends were doing it.", "His mother Monica prayed for him for years and years. Finally, when he was grown up, he changed, and he wrote a whole book to God about his life, saying sorry and thank you.", "He said something people still repeat: our hearts are restless until they rest in God. That is why nothing we buy makes us happy for long." ] },

"Don Quixote": { sections: [
  { h: "What it is", p: [ "Miguel de Cervantes published the first part in 1605 and the second in 1615, a year before his death, after a life as a soldier wounded at Lepanto, a captive in Algiers for five years, and a tax collector twice imprisoned. A poor gentleman of La Mancha reads so many romances of chivalry that he decides to become a knight errant: he names himself Don Quixote, his horse Rocinante, a farm girl his lady Dulcinea, and takes a neighbour, Sancho Panza, as his squire. He charges windmills as giants, frees prisoners who stone him, and is beaten by the world at every turn, while Sancho, who came for an island to govern, slowly begins to see as his master sees.", "The second part is stranger: the characters have read the first part, and the world now plays along with Don Quixote to mock him, which is crueller than the windmills. He regains his senses at the end, and dies, and Sancho begs him to stay mad." ] },
  { h: "The main ideas", l: [ "Books make people: Don Quixote is a man made entirely of reading. The novel is a warning and a celebration at once.", "Two ways of seeing: the knight sees what things should be, the squire sees what they are, and the book never fully decides between them.", "Dignity in failure: he is beaten in every chapter and never stops being a gentleman; the humour is tender, not contemptuous.", "The friendship of opposites: Sancho's proverbs and Don Quixote's speeches educate each other until each has some of the other's eyes.", "Reality answers back: the second part, with the duke and duchess staging adventures for him, shows that the world's mockery is its own madness." ] },
  { h: "Why it still matters", p: [ "It is the first modern novel and, in many surveys, the greatest. It taught fiction to hold two truths at once and to love a fool without lying about him. The phrase 'tilting at windmills' is the smallest part of what it gave the language." ] },
  { h: "For our family", l: [ "Sancho's question to his master, what did you expect, is a good one to ask any plan: the plate, the fast, the training week. Dreams need a squire.", "Don Quixote's courtesy to everyone who beats him is a lesson in losing well.", "Read it aloud with the children for the windmills and the inn; read it alone for the ending." ] },
  { h: "Read next", l: [ "Edith Grossman's translation (2003). Read Part One's first twenty chapters with the children; finish Part Two yourself.", "Cervantes's Exemplary Novels, shorter, for more of his voice." ] } ],
  kids: [ "Don Quixote was a man in Spain who read so many books about knights that he decided to become one. He put on old armour, got on his skinny horse, and rode out to have adventures.", "He saw windmills and thought they were giants, and charged at them with his spear. He got knocked off his horse. His friend Sancho, a farmer on a donkey, kept saying: sir, those are windmills.", "People laughed at him, but he never stopped being kind and brave, even when he lost. The book is funny and also a little sad, and it is one of the most famous stories ever written." ] },

"The Divan of Hafez": { sections: [
  { h: "What it is", p: [ "Shams al-Din Muhammad Hafez of Shiraz (c. 1315–1390) wrote some five hundred ghazals, lyric poems of seven to fifteen couplets each sharing one rhyme, collected after his death into his Divan. He took the name Hafez because he had memorised the Quran, and taught it. The poems speak of love, wine, the beloved's face and hair, the rose and the nightingale, the tavern and the hypocrite preacher, in a language that is at once the vocabulary of worldly love and the code of the mystics, and the poems refuse to settle on one meaning. The Divan is opened at random in Iran to take an omen, and his tomb in Shiraz is visited like a shrine." ] },
  { h: "The main ideas", l: [ "The beloved and the Beloved: every line about the beloved's face can be read of a person or of God, and Hafez keeps both alive on purpose.", "Wine as ecstasy: the tavern is the place where the self is lost; the wine is love, the cupbearer the guide. The images are from the Quran's own promise of a drink in the Garden.", "Against hypocrisy: his constant target is the preacher who forbids in public what he does in private; the rend, the honest rogue, is nearer God than the pious fraud.", "Fate and joy: accept what the heavens send, seize the present hour, and keep faith with love; the ghazals move between resignation and delight.", "The craft: each couplet is complete, each ghazal a necklace of them; the music of the Persian is why they are sung." ] },
  { h: "Why it still matters", p: [ "Hafez is the most loved poet in the Persian language, and Goethe wrote his West-östlicher Divan in his honour. He is read for consolation, for beauty, and for the permission he gives to doubt the pious and love God anyway. His lines are quoted in Urdu as freely as in Persian." ] },
  { h: "For our family", l: [ "His war on hypocrisy is a mirror for parents: children see the gap between what we preach and what we do before they see anything else.", "Read him for the beauty of Persian, which Urdu grew from; the sound teaches before the sense.", "Open the Divan for a line of the day, as the Poem of the day does, and let the family argue about what it means." ] },
  { h: "Read next", l: [ "Dick Davis, Faces of Love: Hafez and the Poets of Shiraz (Penguin), the best English Hafez, with Jahan Malek Khatun and Obayd-e Zakani.", "Peter Avery's complete translation for the whole Divan." ] } ],
  kids: [ "Hafez was a poet from the city of Shiraz, about seven hundred years ago. He knew the whole Quran by heart, which is why he is called Hafez, the one who memorised it.", "He wrote short poems that sound like songs, about love and roses and nightingales. The grown-ups argue about whether he is writing about a person or about Allah, and he liked it that way.", "He did not like people who pretend to be good but are not. He said it is better to be honest about your mistakes than to show off. People in Iran open his book to find a line for the day." ] },

"The Shahnameh": { sections: [
  { h: "What it is", p: [ "Abu al-Qasim Ferdowsi of Tus spent about thirty years on the Shahnameh, the Book of Kings, finishing it around 1010: some fifty thousand couplets telling the history of Iran from the creation of the world to the Arab conquest, in three movements, mythical, heroic and historical. The tyrant Zahhak with snakes on his shoulders and the blacksmith Kaveh who raised his apron as a banner; Rostam, the great champion, and his seven labours; Rostam's unknowing fight with his own son Sohrab; Siyavash the innocent prince; the long wars with Turan; and the Sasanian kings down to Yazdegerd. Ferdowsi wrote it to preserve the Persian language and memory, and he largely succeeded: modern Persian is readable back to his lines." ] },
  { h: "The main ideas", l: [ "Fathers and sons: the tragedy of Rostam and Sohrab, who meet in battle without knowing each other, is the book's heart, and its lesson about pride, secrecy and the cost of not asking a name.", "Justice and tyranny: Zahhak's reign of snakes fed on the brains of the young is the image of a state that devours its own; Kaveh's uprising is the image of the just rebellion.", "The hero's limits: Rostam is strong, loyal and mortal, and his greatest wounds are self-inflicted.", "Wisdom over strength: the book's refrain is that knowledge is the crown and reason the better sword; kings fall when they stop listening.", "Memory as a duty: a people that forgets its stories becomes someone else's." ] },
  { h: "Why it still matters", p: [ "The Shahnameh is to Persian what Homer is to Greek and more, since it is still read and recited by ordinary people. Its stories are the common property of Iran, Afghanistan, Tajikistan and the Persian-reading parts of the subcontinent, and its lesson about fathers and sons is told to every boy who thinks he is stronger than his father." ] },
  { h: "For our family", l: [ "Rostam and Sohrab is the story to tell when a father and a son are not talking. Ask the name.", "Kaveh the blacksmith is the ordinary man who said no to the tyrant: a lesson about courage without rank.", "Ferdowsi worked thirty years on one book for his people. Long work for others is itself a story." ] },
  { h: "Read next", l: [ "Dick Davis, Shahnameh: The Persian Book of Kings (Penguin), a prose and verse abridgement that keeps the great stories.", "Davis's standalone Rostam: Tales of Love and War for the hero's cycle." ] } ],
  kids: [ "Ferdowsi was a poet who spent thirty years writing the story of all the kings and heroes of Persia, from the beginning of the world. It is one of the longest poems ever written.", "The bravest hero is Rostam, who fights monsters and dragons. But the saddest story is about Rostam fighting a young champion without knowing it is his own son, Sohrab.", "There is also a wicked king called Zahhak with snakes growing from his shoulders, and a brave blacksmith called Kaveh who stood up to him with his leather apron on a stick as a flag." ] },

"Kulliyat-e-Iqbal": { sections: [
  { h: "What it is", p: [ "The collected poetry of Muhammad Iqbal (1877–1938), in Urdu and Persian: Bang-e-Dara (1924), with the early nature poems, the Shikwa and Jawab-e-Shikwa; Bal-e-Jibril (1935), his finest Urdu; Zarb-e-Kalim (1936); Armaghan-e-Hijaz; and in Persian, Asrar-e-Khudi (1915) and Rumuz-e-Bekhudi, the Payam-e-Mashriq written in answer to Goethe, the Zabur-e-Ajam, and the Javid Nama, his journey through the heavens in the company of Rumi. Iqbal trained in philosophy at Cambridge and Munich, practised law in Lahore, and gave the 1930 Allahabad address that imagined a Muslim state in the north-west of India." ] },
  { h: "The main ideas", l: [ "Khudi, selfhood: the self is not an illusion to be dissolved but a reality to be strengthened, by love, by desire for the great, by courage and by faith, until Allah Himself asks the servant what he wishes.", "Against passivity: Iqbal's quarrel with the decadent Sufism and the resigned religion of his time; the believer is an eagle, not a vulture, and the shaheen does not build a nest.", "The Shikwa and its answer: the complaint to God that Muslims have been abandoned, and God's answer that they abandoned their own faith's energy.", "Love over intellect: 'ishq, the burning devotion of Rumi, completes the reason of the philosophers.", "The Muslim community as a nation of faith, not of land or race; and the Quran as a living book, to be read as if it were being revealed to you." ] },
  { h: "Why it still matters", p: [ "Iqbal is the national poet of Pakistan and the most quoted Urdu poet of the twentieth century; his lines are on classroom walls and in political speeches. His doctrine of khudi is a philosophy of self-respect and effort addressed to a people he thought had gone to sleep, and it still reads as a wake-up call." ] },
  { h: "For our family", l: [ "Khudi ko kar buland itna: raise yourself so high that before every decree God asks what you want. The verse to teach the children before any other.", "Iqbal's eagle, who does not build a nest, is the fast and the training: do not settle into comfort.", "Read the Quran as if it were revealed to you, he said; the daily reading is that practice." ] },
  { h: "Read next", l: [ "Bal-e-Jibril, the whole collection, in Urdu with a translation beside it; Khushwant Singh's Shikwa and Jawab-e-Shikwa; Mustansir Mir's Tulip in the Desert for selected poems with commentary.", "The Reconstruction of Religious Thought in Islam, his lectures, for the philosophy behind the verse." ] } ],
  kids: [ "Allama Iqbal was a poet from Sialkot who dreamed of Pakistan before it existed. He wrote in Urdu and Persian, and his poems are sung at school.", "His big idea is called khudi: believe in yourself, work hard, and have courage, and Allah will help you. He said a believer should be like an eagle that flies high and does not sit in a lazy nest.", "His most famous line says: make yourself so great that before Allah writes your fate, He asks you: tell Me, what do you want?" ] },

"Al-Sahifa al-Sajjadiyya": { sections: [
  { h: "What it is", p: [ "A collection of fifty-four supplications attributed to Imam 'Ali ibn al-Husayn, Zayn al-'Abidin, al-Sajjad (d. 713), the great-grandson of the Prophet who survived Karbala as a young man and spent the rest of his life in worship and teaching in Madinah. The duas are addressed to Allah on every occasion of a life: praise, blessings on the Prophet and his household, for parents, for children, for neighbours and friends, for the people of the frontiers, in illness, when wronged, on the morning and evening, on hearing thunder, in Ramadan and on its ending, at the end of a day, for noble character, the Makarim al-Akhlaq. The Bayan study records the attribution as received through its chains and the text as transmitted from the ninth century; the standard printed edition is the one the Shia tradition has used for centuries." ] },
  { h: "The main ideas", l: [ "Prayer as moral education: the dua for noble character is a complete programme of virtue phrased as requests, so that asking for a trait is the first step to having it.", "Gratitude as the root: supplication after supplication begins by counting blessings before asking.", "Rights of others: the duas for parents, children and neighbours are practical lists of what each is owed, in the form of asking for the strength to pay.", "Honesty about weakness: the Imam confesses fear, laziness and the pull of the self with a frankness that makes the book usable by anyone.", "Beauty of language: the Sahifa is also one of the monuments of Arabic prose, which is why it has been called the Psalms of the House of the Prophet." ] },
  { h: "Why it still matters", p: [ "Where other books tell you what to be, the Sahifa gives you the words to ask for it. Its dua for parents and its dua for children are read at the table in homes across the Muslim world, and its dua for noble character is the single best short description of the person OnePlate is trying to help you become." ] },
  { h: "For our family", l: [ "Read the dua for parents (Supplication 24) with the children on Friday; read the dua for children (25) yourself.", "The Makarim al-Akhlaq (20) is the family's character curriculum in one prayer; take one line a week.", "The morning and evening dua (6) is the day's frame: a prayer at each end of the fast." ] },
  { h: "Read next", l: [ "William Chittick's translation, The Psalms of Islam (Muhammadi Trust), with Arabic facing.", "Then the Treatise on Rights, attributed to the same Imam, the prose companion." ] } ],
  kids: [ "Imam Zayn al-'Abidin was the great-grandson of the Prophet ﷺ. He prayed so much that he was called the ornament of the worshippers.", "This book is a collection of his duas, beautiful ways of talking to Allah: when you wake up, when you are sick, for your mother and father, for your friends, for your neighbours, and to have a good character.", "One of the duas asks Allah: help me to be kind to my parents and to speak softly to them. We can read a line of it together before dinner." ] },

"Nahj al-Balagha": { sections: [
  { h: "What it is", p: [ "Al-Sharif al-Radi (d. 1015), a scholar and poet of Baghdad, compiled from earlier sources what he judged the most eloquent sermons, letters and sayings of Imam 'Ali ibn Abi Talib (d. 661), the Prophet's cousin and son-in-law and the fourth caliph. The Way of Eloquence has three parts: some two hundred and forty sermons, including the sermon on creation, the Shiqshiqiyya on the caliphate, and the sermon of the God-fearing describing the muttaqin; seventy-nine letters, including the long letter of instruction to Malik al-Ashtar as governor of Egypt, and the letter of advice to his son al-Hasan; and about four hundred and eighty short sayings. Al-Radi chose for eloquence, so the chains of transmission are not given in the book itself; later scholars have traced most pieces to earlier works, and the Bayan study labels each as graded or received." ] },
  { h: "The main ideas", l: [ "Piety described in action: the sermon of the muttaqin lists them as people whose speech is truthful, whose dress is modest, whose walk is humble, and who are never satisfied with their own good deeds.", "Justice as the measure of rule: the letter to Malik orders the governor to see the people as either brothers in faith or equals in creation, to prefer the common people to the elite, and to make mercy his garment.", "The world as a passage: sermon after sermon describes the world as a bridge and a market where provisions are gathered for the journey, and warns against attachment without despising work.", "Knowledge and intellect: knowledge guards you while you guard wealth; the tongue of the wise is behind his heart.", "Self-reckoning: take account of yourselves before you are taken to account; weigh yourselves before you are weighed." ] },
  { h: "Why it still matters", p: [ "Nahj al-Balagha is the second book of Arabic after the Quran in the Shia tradition and admired across the Sunni world for its prose. The letter to Malik al-Ashtar is read as a charter of just government in Muslim and non-Muslim universities, and its sayings supply a proverb for every situation of a working life." ] },
  { h: "For our family", l: [ "The letter to al-Hasan (Letter 31) is a father's advice to a son and the Learn tab's Teaching cards draw on it; read it yourself in one sitting.", "The sayings are built for the dinner table: one a night, and ask the children what it means.", "The letter to Malik is the manual for anyone with authority over others, including a father over a household: mercy as the garment." ] },
  { h: "Read next", l: [ "The translation by Sayed Ali Reza (Peak of Eloquence) is widely available; Tahera Qutbuddin's recent edition and translation of the sayings is the scholarly standard.", "Read first: Sermon 193 (the God-fearing), Letter 31, Letter 53, and the sayings from 1 to 50." ] } ],
  kids: [ "Imam 'Ali was the Prophet's cousin, raised in his house, and later the leader of all the Muslims. He was famous for speaking so well that people wrote down what he said.", "This book has his speeches, his letters, and hundreds of short wise sayings, like: knowledge is better than money, because knowledge looks after you, but you have to look after money.", "In a letter to a governor he said: every person you meet is either your brother in religion or your equal as a human, so be kind to all of them." ] },

"The Prophet of Islam": { sections: [
  { h: "What it is", p: [ "The sirah, the biography of the Prophet Muhammad ﷺ, as it was first written down: Ibn Ishaq of Madinah (d. c. 767) gathered the reports of the Prophet's life into a book that survives mainly in the edition of Ibn Hisham (d. 833), who abridged and annotated it. Later works, al-Waqidi's Maghazi on the campaigns, Ibn Sa'd's Tabaqat on the Companions, and the sirah sections of al-Tabari, drew on the same material. The arc is fixed: Makkah, the orphan, the trader, the marriage to Khadijah, the cave of Hira and the first revelation, the persecution, the emigration to Abyssinia, the year of sorrow, the Isra, the pledges of 'Aqabah; Madinah, the constitution, Badr, Uhud, the Trench, Hudaybiyyah, the letters to kings, the conquest of Makkah, Hunayn, Tabuk, the farewell pilgrimage, the death.", "The Bayan Library's note applies: the sirah is a narrative source, graded report by report; the events are certain in outline and debated in detail." ] },
  { h: "The main ideas", l: [ "Character before mission: forty years as al-Amin, the trustworthy, before a word of revelation. The Makkans believed his honesty even when they rejected his message.", "Patience in Makkah: thirteen years of calling with no state, no army and no permission to fight, in which the community was formed by prayer, recitation and endurance.", "The constitution of Madinah: a written agreement between the Muslims, the tribes of Madinah and the Jewish clans, the first charter of a plural city.", "Mercy in victory: the conquest of Makkah without reprisals, and the words to the people who had persecuted him for twenty years: go, you are free.", "The household: a man who mended his own sandals, milked his own goats, served his family, played with his grandchildren, and said the best of you is the best to his family.", "The farewell sermon: no Arab has superiority over a non-Arab except by piety; your blood and property are sacred to one another; I have left among you what will keep you from going astray." ] },
  { h: "Why it still matters", p: [ "The sirah is the context of the Quran and the model the Quran names: in the Messenger of Allah you have a beautiful example. Every virtue OnePlate asks for, moderation in eating, kindness at home, consultation, gentleness, patience, is first a scene from his life." ] },
  { h: "For our family", l: [ "Read the Makkan years to the children first: the orphan, the shepherd, the cave, the persecution. The example of patience comes before the example of power.", "His eating: one-third rule, sitting to eat, never criticising food, eating with his family. The Thuluth rule is his table.", "His home: a father who stood for his daughter Fatimah when she entered, and seated her in his place." ] },
  { h: "Read next", l: [ "Martin Lings, Muhammad: His Life Based on the Earliest Sources, the most readable sirah in English, drawn from Ibn Ishaq and Ibn Sa'd.", "Alfred Guillaume's translation of Ibn Ishaq for the source itself; Tariq Ramadan's In the Footsteps of the Prophet for the lessons." ] } ],
  kids: [ "The Prophet Muhammad ﷺ was born in Makkah in the Year of the Elephant. His father died before he was born and his mother when he was six, so his grandfather and then his uncle looked after him.", "Everyone in Makkah called him al-Amin, the honest one, because he never lied. When he was forty, the angel Jibril came to him in a cave and said: Read! That was the start of the Quran.", "For years people were cruel to him, but he was patient and kind. When he finally returned to Makkah as the leader, he forgave everyone. At home he helped with the housework and played with his grandchildren." ] },

"Elements": { sections: [
  { h: "What it is", p: [ "Euclid of Alexandria, around 300 BCE, arranged the geometry and number theory of the Greeks into thirteen books built from definitions, five postulates and five common notions, from which every proposition is proved in order: the construction of an equilateral triangle in the first proposition; the theorem of Pythagoras at the end of Book I; the theory of proportion in Book V; similar figures; number theory, including the infinitude of primes and the Euclidean algorithm, in Books VII to IX; incommensurables in Book X; and the five regular solids in Book XIII. It was translated into Arabic under al-Ma'mun by al-Hajjaj and again by Ishaq ibn Hunayn, commented on by Thabit ibn Qurra, Ibn al-Haytham and Nasir al-Din al-Tusi, and reached Europe through those Arabic versions. It was the textbook of geometry for twenty-two centuries." ] },
  { h: "The main ideas", l: [ "Proof: a claim is accepted because it follows by steps from what was already accepted, down to a few starting points everyone grants. Nothing is taken on authority.", "Axioms: five postulates about lines and circles, and five common notions such as 'things equal to the same thing are equal to each other', carry the whole structure.", "Order: each proposition uses only what came before, so the book is a single argument, and a student who understands Book I has learned how to think, not just how to measure.", "The parallel postulate: the fifth, which looked less obvious than the others, was questioned by Thabit, Ibn al-Haytham, Omar Khayyam and al-Tusi, and that questioning led, two thousand years later, to the non-Euclidean geometries of Einstein's universe.", "Beauty: the proof that there are infinitely many primes, in Book IX, is still taught as the model of an elegant argument." ] },
  { h: "Why it still matters", p: [ "The Elements taught the world what a proof is. Lincoln studied it to learn to argue; Newton wrote the Principia in its form; the Islamic mathematicians who questioned its fifth postulate opened the door to modern geometry. Learning geometry from Euclid is still the best way to learn that truth can be built." ] },
  { h: "For our family", l: [ "Do Proposition 1 with a compass and a ruler at the table: the equilateral triangle. A child who draws it has done a proof.", "The habit of asking 'what does this follow from' is Euclid's gift to arguments at home.", "The Pythagorean theorem is the fence post, the ladder and the diagonal of the room: show it in the house." ] },
  { h: "Read next", l: [ "Book I in Thomas Heath's translation, or the beautiful Oliver Byrne colour edition (1847) reprinted by Taschen, which proves with diagrams.", "Then Book IX, Proposition 20: the primes are infinite." ] } ],
  kids: [ "Euclid was a mathematics teacher in Egypt more than two thousand years ago. He wrote a book of geometry that people used in school for over two thousand years.", "He started with a few simple facts everyone agrees on, like: you can draw a straight line between any two points. Then he proved everything else step by step from those.", "You can do his very first proof with a ruler and a compass: draw a triangle with three equal sides. When you do it, you are doing exactly what students did two thousand years ago." ] },

"The Compendious Book on Calculation": { sections: [
  { h: "What it is", p: [ "Muhammad ibn Musa al-Khwarizmi wrote al-Kitab al-Mukhtasar fi Hisab al-Jabr wa al-Muqabala in Baghdad around 820, at the House of Wisdom under the caliph al-Ma'mun. The title gave us the word algebra, al-jabr, the restoring of a subtracted term to the other side of an equation, and his name gave us algorithm, through the Latin of his other book on calculation with Hindu numerals. The book shows how to reduce any linear or quadratic problem to one of six standard forms, solve each by a rule, and prove the rule by a geometric figure; then it applies the method to trade, surveying and the division of inheritances under Islamic law, which take up more than half the book." ] },
  { h: "The main ideas", l: [ "Reduction: every problem, however it is stated, can be moved into a standard form by two operations, al-jabr, restoring, and al-muqabala, balancing. The method is the discovery.", "Rules with proofs: each rule for solving a quadratic is justified by completing a square, drawn as an actual square.", "Mathematics for use: the examples are prices, measures and inheritance shares; the book exists because people needed to divide estates correctly.", "No symbols: everything is in words and numbers; the letter x came centuries later. The ideas came first.", "Hindu numerals: his other treatise introduced the decimal digits and zero to the Islamic world and thence to Europe, where they were called Arabic numerals." ] },
  { h: "Why it still matters", p: [ "Every equation solved in every school is al-Khwarizmi's method. His insistence on stating a general procedure that works on any instance is what the word algorithm now means, and the computers that run on algorithms carry his name in a Latin spelling." ] },
  { h: "For our family", l: [ "The inheritance problems are the Quran's shares turned into arithmetic; the book is a reminder that the law asked for mathematics.", "Teach a child balancing with coins on two sides of a scale: what you do to one side you do to the other. That is al-muqabala.", "The word algorithm on every device comes from a man in Baghdad who wanted to divide estates fairly." ] },
  { h: "Read next", l: [ "Frederic Rosen's 1831 translation is free online; Roshdi Rashed's edition is the scholarly text.", "Jim Al-Khalili, The House of Wisdom, for the Baghdad in which it was written." ] } ],
  kids: [ "Al-Khwarizmi was a mathematician in Baghdad twelve hundred years ago. He wrote a book about how to solve puzzles with unknown numbers, like: a number plus ten equals twenty-two, what is the number?", "The name of his book, al-jabr, became the word algebra. And his own name became the word algorithm, which is what computers follow step by step.", "He also taught people the numbers we use today, 1 2 3 4 5 6 7 8 9 and 0, which came from India. Before that, people used letters, and sums were very hard." ] },

"On the Origin of Species": { sections: [
  { h: "What it is", p: [ "Charles Darwin published the Origin in 1859, twenty years after the voyage of the Beagle, when a letter from Alfred Russel Wallace showed that another naturalist had reached the same idea. It is one long argument, as he called it: variation exists in every population; more are born than can survive; those whose variations fit their conditions leave more offspring; over long time this natural selection shapes populations into new forms, and the diversity of life descends from common ancestors. He draws on pigeon breeding, the geographical distribution of species, the fossil record, embryology, and the oddities of island life, and he faces the difficulties, the gaps in the record and the eye, in chapters of their own." ] },
  { h: "The main ideas", l: [ "Variation and inheritance: individuals differ, and differences are passed on; he did not know how, since Mendel's work was unknown to him.", "The struggle for existence: Malthus applied to all life; far more seeds, eggs and young than can live.", "Natural selection: the differences that help survive and breed accumulate; the breeder's choice done by circumstances over ages.", "Common descent: the tree of life, in which similar forms are relatives, not separate designs.", "Deep time: the earth is old enough for small changes to add up to the differences we see.", "Humility of method: he states the objections to his own theory more clearly than his opponents did." ] },
  { h: "Why it still matters", p: [ "It is the founding book of modern biology and the reason medicine understands antibiotic resistance, vaccines and genetics. Its account of how small advantages compound over time is also the clearest statement of why small daily habits matter. Muslim scholars have read it variously; Tabataba'i discusses the origins of species in al-Mizan and holds that the Quran teaches the special creation of the human being while leaving the mechanisms of natural history to inquiry." ] },
  { h: "For our family", l: [ "Small differences, repeated, become large: the Origin's logic is the logic of a thumb of oil a day.", "Read Darwin's chapter on the difficulties of the theory with older children: here is how an honest person argues against himself.", "The Quran's call to look at the camel and the bee is a call to natural history; the book is one answer to that call." ] },
  { h: "Read next", l: [ "The first edition (1859), which is the clearest; read the Introduction, Chapters III and IV, and the last chapter.", "Then Darwin's Voyage of the Beagle, the travel book that started it." ] } ],
  kids: [ "Charles Darwin sailed around the world on a ship called the Beagle for five years, collecting birds, beetles, fossils and plants, and writing down everything.", "He noticed that animals of one kind are all a little different, and that the ones whose differences help them survive have more babies. Over a very long time, these small differences add up and animals change.", "His book explains how the many kinds of living things are related to each other, like a giant family tree. Scientists still use his ideas every day, for example to understand how germs change." ] },

"The Brothers Karamazov": { sections: [
  { h: "What it is", p: [ "Dostoevsky's last novel, finished in 1880, a few months before his death. Fyodor Karamazov, a buffoon and sensualist, has three sons: Dmitri, a soldier ruled by passion, who competes with his father for the same woman and the same money; Ivan, an intellectual who cannot accept a world in which children suffer; and Alyosha, a novice in the monastery under the elder Zosima. There is also Smerdyakov, the servant who may be a fourth son. The father is murdered; Dmitri is tried and convicted; the truth is otherwise. Inside the story Ivan tells Alyosha his poem of the Grand Inquisitor, in which Christ returns to Seville and is arrested by the Church, and Zosima's life and teachings are given in full." ] },
  { h: "The main ideas", l: [ "If God does not exist, everything is permitted: Ivan's thesis, which the novel tests to destruction in Smerdyakov's act.", "The problem of suffering: Ivan's catalogue of tortured children and his returning of the ticket is the strongest case against faith ever put by a believer.", "The Grand Inquisitor: people will trade freedom for bread, miracle and authority; the question is whether freedom is a gift or a burden.", "Active love: Zosima's teaching that love in action is a harsh and dreadful thing compared with love in dreams, and that each is responsible for all.", "Guilt and brotherhood: all three brothers wanted the father dead in some way; the novel refuses to let any of them be innocent or any be only guilty.", "The children: the subplot of Ilyusha and the boys, and Alyosha's speech at the stone, is the novel's answer: memory of one good moment can save a life." ] },
  { h: "Why it still matters", p: [ "Many readers consider it the greatest novel written. It takes faith and doubt with equal seriousness and lets each speak at full strength, which almost no book does. Its teaching on active love and on the responsibility of each for all reads, to a Muslim, like a commentary on 5:32." ] },
  { h: "For our family", l: [ "Zosima's line, love in action is harsh and dreadful compared with love in dreams, is the cure for sentimental parenting.", "Alyosha's speech at the stone: give a child one memory of being loved and brave, and it will be a lantern for life. That is the family circle's purpose.", "Read it when you are ready for it; it is long and it changes people." ] },
  { h: "Read next", l: [ "Richard Pevear and Larissa Volokhonsky's translation; begin with Book V (Pro and Contra) if you want the argument first, or Book I if you want the family.", "Crime and Punishment, shorter, before it." ] } ],
  kids: [ "This is a long Russian story about a father and his three sons, who are all very different: one is hot-tempered, one is clever and full of questions, and one, Alyosha, is gentle and wants to be a monk.", "Something terrible happens in the family, and the story asks hard questions: why do bad things happen, what is freedom, and how should we love each other?", "At the very end, Alyosha tells a group of boys: remember this one day when we were all good and kind together, and that memory will keep you safe your whole life." ] },

"The Thousand and One Nights": { sections: [
  { h: "What it is", p: [ "A frame tale and the stories told inside it. King Shahriyar, betrayed by his wife, marries a new bride each night and has her killed in the morning, until Shahrazad, the vizier's daughter, marries him and tells a story every night that she leaves unfinished at dawn, for a thousand and one nights, until he is cured. The stories come from Persian, Indian, Arabic, Egyptian and Syrian sources over six centuries, the earliest layer a Persian collection called the Thousand Tales translated into Arabic in Baghdad by the ninth century. The merchant and the jinni, the fisherman and the jinni, the porter and the three ladies, the hunchback, Sindbad's seven voyages. Aladdin and Ali Baba were added by the French translator Antoine Galland in the eighteenth century from a Syrian storyteller, and are not in the older Arabic manuscripts." ] },
  { h: "The main ideas", l: [ "Stories save lives: Shahrazad's art turns a murderer back into a king. The book is the defence of storytelling.", "Nesting: tales inside tales inside tales, each one earning the next, a structure that taught the world's novelists.", "The city: Baghdad, Cairo and Basra of merchants, caliphs in disguise, barbers who talk too much, and women who are cleverer than the men.", "Fortune's wheel: the porter becomes rich, the rich man is ruined, and the moral is seldom simple; patience and wit are rewarded more than virtue.", "Harun al-Rashid walking the night streets is the book's image of a ruler who wants to know his people." ] },
  { h: "Why it still matters", p: [ "The Nights gave the world Sindbad and the jinni in the bottle, shaped Boccaccio, Chaucer and Borges, and remains the most widely read work of Arabic literature. Its frame is also the truest account of why a family reads together: a story a night, unfinished, so there is a reason to come back." ] },
  { h: "For our family", l: [ "Shahrazad's rule: stop the story before the end, and say 'tomorrow'. The Learn tab's daily set works the same way.", "Sindbad's seven voyages, one a week, are the children's introduction to the sea, trade and risk.", "The clever women of the Nights are good company for a daughter." ] },
  { h: "Read next", l: [ "Husain Haddawy's translation of the fourteenth-century Syrian manuscript (Norton) for the core; Malcolm Lyons's three-volume Penguin for everything.", "For children: the Sindbad cycle and the Fisherman and the Jinni, in any good retelling." ] } ],
  kids: [ "A long time ago there was a king who was so angry that he decided to marry a new wife each day and have her killed the next morning. A clever girl called Shahrazad married him and every night told him a story so exciting that she stopped in the middle at dawn.", "The king had to let her live to hear the end. She did this for a thousand and one nights, and by then the king had changed and did not want to hurt anyone.", "Her stories are famous all over the world: Sindbad the sailor and his seven voyages, the fisherman who found a jinni in a bottle, and Ali Baba and the forty thieves." ] },

"Tao Te Ching": { sections: [
  { h: "What it is", p: [ "Eighty-one short chapters in verse, attributed to Laozi, the Old Master, said to have been a keeper of archives who wrote the book at the request of a gatekeeper when he left China for the west; the text as we have it was composed around the fourth century BCE. The Tao, the Way, is the source and pattern of all things, which cannot be named; the te is the power or virtue of living in accord with it. The book is addressed, often, to a ruler, and its advice is to do less: to govern a large state like cooking a small fish, without stirring." ] },
  { h: "The main ideas", l: [ "Wu wei, non-forcing: act in accordance with the grain of things, as water does, and the hard is worn away by the soft.", "The valley and the low place: the sage takes the low ground, as water does, and so all things flow to him.", "Emptiness is use: the hub's hole makes the wheel useful; the empty room is the room; what is not there does the work.", "The Way of nature is to reduce excess and supply what is lacking; the way of people is the reverse.", "Knowing when to stop: fill a cup to the brim and it spills; sharpen a blade too much and it dulls; retire when the work is done.", "The three treasures: compassion, frugality and not daring to be first in the world." ] },
  { h: "Why it still matters", p: [ "The Tao Te Ching is the most translated book after the Bible, and its counsel of restraint, patience and softness reaches readers in every tradition. Its three treasures, compassion, frugality and humility, could be a summary of the Quran's servants of the Merciful." ] },
  { h: "For our family", l: [ "Knowing when to stop is the whole of the plate: the cup filled to the brim spills.", "The soft overcomes the hard: the parent who waits often wins what the parent who shouts loses.", "Emptiness is use: an evening with nothing planned is where the family circle happens." ] },
  { h: "Read next", l: [ "D. C. Lau's translation (Penguin) for accuracy; Stephen Mitchell's for beauty; read chapters 8, 11, 33, 44, 67 first.", "Then the Zhuangzi, funnier and wilder." ] } ],
  kids: [ "A very old Chinese book, written by a wise man called Laozi, about the Way, which means the way things naturally are.", "It says: be like water. Water is soft, but it wears down the hardest rock. It goes to the low places, and that is why rivers and seas are so big.", "It also says: if you fill a cup right to the top, it spills. Know when to stop. That is good advice for eating, for talking, and for playing games." ] },

"Essays": { sections: [
  { h: "What it is", p: [ "Michel de Montaigne retired to his tower in 1571, at thirty-eight, and began writing what he called essais, attempts, trials of his own judgement on whatever subject came to hand: on idleness, on liars, on fear, on the education of children, on friendship, written for his dead friend Étienne de La Boétie, on cannibals, on the custom of wearing clothes, on books, on cruelty, on presumption, on repentance, and finally on experience. Three books, revised to his death in 1592, with the motto he had struck on a medal: Que sais-je? What do I know? He invented the essay and made himself its subject, on the principle that each man carries the whole form of the human condition." ] },
  { h: "The main ideas", l: [ "Self-study as a method: look honestly at your own inconsistency and you learn more about people than from any system.", "Scepticism without despair: we know less than we think, so hold opinions loosely and cruelty is never justified by certainty.", "Custom is a tyrant: what seems natural is mostly habit; the cannibals, he argues, are less barbarous than the Europeans who burn heretics.", "Education by conversation: teach a child to judge, not to memorise; travel, talk, and let him digest what he reads.", "Friendship: the rarest thing, in which two wills merge; because it was he, because it was I.", "The body is not the enemy: eat, sleep, be ill and get well with attention and without self-hatred; the last essay, on experience, is the wisest thing written on living in a body." ] },
  { h: "Why it still matters", p: [ "Montaigne is the most companionable writer in any language. He taught the world to think in the first person without vanity, and his essay on experience, written in pain from kidney stones, is a manual for living kindly with one's own flesh that OnePlate would be happy to have as an epigraph." ] },
  { h: "For our family", l: [ "On the education of children: judgement before memory, conversation before lecture. The Learn tab's questions are Montaigne's method.", "On experience: notice what your body actually tells you, after meals, after sleep, and trust the record more than the rule.", "What do I know? A good sentence for a parent to say aloud, now and then, in front of the children." ] },
  { h: "Read next", l: [ "M. A. Screech's or Donald Frame's complete translation; read 'On the education of children', 'On friendship', 'On cannibals' and 'On experience'.", "Sarah Bakewell, How to Live: A Life of Montaigne, for the man." ] } ],
  kids: [ "Montaigne was a French writer who lived in a tower full of books about four hundred and fifty years ago. He invented a new kind of writing: short pieces where he just thought out loud about anything, called essays.", "He wrote about friendship, about fear, about children, about his cat, about what he ate. His favourite question was: what do I really know? He was honest about not being sure.", "He said children should be taught to think for themselves and to talk about ideas, not just to memorise. That is why we ask questions at the dinner table." ] },
};
